import { useState } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Header from "./components/Header";
import NavBar from "./components/NavBar";
import Footer from "./components/Footer";
import QuranPage from "./pages/QuranPage";
import HadithPage from "./pages/HadithPage";
import DuasPage from "./pages/DuasPage";
import PillarsPage from "./pages/PillarsPage";
import ConceptsPage from "./pages/ConceptsPage";
import BooksPage from "./pages/BooksPage";
import AdvancedPage from "./pages/AdvancedPage";
import AudioPage from "./pages/AudioPage";

export default function App() {
  const [dark, setDark] = useState(false);
  const [lang, setLang] = useState("en");
  const [search, setSearch] = useState("");

  return (
    <Router>
      <div className="topbar">
        Free Islamic Resources &nbsp;|&nbsp;
        <span>Books &gt;17,000</span> •
        <span>Audio &gt;10,000</span> •
        <span>Videos &gt;50,000</span>
        &nbsp;| Always free, always authentic
      </div>

      <Header dark={dark} setDark={setDark} lang={lang} setLang={setLang} search={search} setSearch={setSearch} />
      <NavBar />

      <main className="main">
        <Routes>
          <Route path="/" element={<QuranPage />} />
          <Route path="/hadith" element={<HadithPage />} />
          <Route path="/duas" element={<DuasPage />} />
          <Route path="/pillars" element={<PillarsPage />} />
          <Route path="/concepts" element={<ConceptsPage />} />
          <Route path="/books" element={<BooksPage />} />
          <Route path="/advanced" element={<AdvancedPage />} />
          <Route path="/audio" element={<AudioPage />} />
        </Routes>
      </main>

      <Footer />
    </Router>
  );
}
